import{_ as o,o as t,c as a,a0 as r}from"./chunks/framework.BWpMpcZ2.js";const c=JSON.parse('{"title":"Images","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/images.md","filePath":"configuration/images.md"}'),s={name:"configuration/images.md"};function i(n,e,d,l,g,m){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to &quot;Images&quot;">​</a></h1><p>Images live in your workspace&#39;s <code>assets/</code> folder and travel with it — upload once, reference as plain Markdown (<code>![alt](assets/...)</code>) forever. Full workflow (upload, resize, align, captions) is in the <a href="./../writing-guide.html#images">Writing Guide</a>; <a href="./../debugging.html#image-issues">Debugging</a> covers broken references and failed generations.</p><h2 id="settings-→-images" tabindex="-1">Settings → Images <a class="header-anchor" href="#settings-→-images" aria-label="Permalink to &quot;Settings → Images&quot;">​</a></h2><p>Providers, looks, and ComfyUI workflows are configured in <strong>Settings → Images</strong>:</p><ul><li><strong>Providers</strong> — OpenAI-compatible endpoints, Stability, FAL, Google Gemini, or local ComfyUI. The editor never cares which one produced the image. Configure credentials, then <strong>Test provider</strong> before generating.</li><li><strong>ComfyUI Workflows</strong> — Import your own API-format workflows into two slots: a <strong>text-to-image workflow</strong> for Imagine and an <strong>image edit workflow</strong> (with a <code>LoadImage</code> input) for Imagine again. Each slot accepts an optional <strong>seed mapping</strong> so every run gets a fresh random seed; without one, the workflow&#39;s saved seed is reused verbatim. Your workflows are never modified — margin overlays prompt, reference, and seed onto a per-run copy.</li><li><strong>Looks</strong> — Look suffixes appended to your prompt. Shipped looks (<code>Cinematic</code>, <code>Illustration</code>) can be edited, hidden (Restore brings them back), or reset; add your own below the list. <code>None</code> is never deletable and means no suffix.</li></ul><h2 id="generation-history" tabindex="-1">Generation history <a class="header-anchor" href="#generation-history" aria-label="Permalink to &quot;Generation history&quot;">​</a></h2><p>Every run is recorded under <strong>History → Images</strong> in the assistant sidebar (newest first, refetched on open): thumbnail, prompt, timestamp, seed, provider. Click an entry for full details — input/output images, submitted prompt, paths — plus Copy prompt and Open-folder actions. Delete individual entries with the hover × button; asset files are kept on disk.</p><p>Logs live in your workspace at <code>outputs/image_logs/images.json</code> (prompt, submitted text, seed, asset path) — separate from chat <code>ai_logs/</code>.</p>',8)])])}const u=o(s,[["render",i]]);export{c as __pageData,u as default};
